// Combines the rule score with the LLM adjustment and picks the route.
// Thresholds from section 4.6; move them to a config table later.
const CONFIG = {
  auto_approve_below: 20,
  investigate_at: 50,
  min_signs_for_investigation: 2,
  llm_max: 40,
  // Claims up to this amount (TND) can be approved without a person. There is no policy number on
  // the claim any more, so the limit is a setting here instead of a field of the policy.
  auto_approval_limit: 2000,
};

const rules = $('Rule Score').all();

return $input.all().map((item, i) => {
  const base = rules[i].json;

  // Some models write their reasoning (<think>...</think>) or extra text
  // around the JSON, so look for the last object that has llm_adjustment.
  const llm_raw = String(item.json.text ?? item.json.output ?? '');
  const raw = llm_raw
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/```json|```/g, '')
    .trim();
  let llm = { llm_adjustment: 0, justification: '', additional_concerns: [] };
  let llm_error = null;
  let parsed = null;
  const candidates = [raw, ...(raw.match(/\{[^{}]*\}/g) || []).reverse()];
  for (const c of candidates) {
    try {
      const p = JSON.parse(c);
      if (p && typeof p === 'object' && 'llm_adjustment' in p) { parsed = p; break; }
    } catch (e) { /* try the next candidate */ }
  }
  if (parsed) llm = { ...llm, ...parsed };
  else llm_error = llm_raw.trim() ? 'LLM output did not contain the expected JSON (see llm_raw)' : 'LLM returned an empty answer';

  let adj = Math.round(Number(llm.llm_adjustment));
  if (!Number.isFinite(adj)) adj = 0;
  adj = Math.max(0, Math.min(adj, CONFIG.llm_max));
  // The design requires every LLM adjustment to be justified in writing.
  if (adj > 0 && !String(llm.justification || '').trim()) adj = 0;

  const risk = Math.min(base.rule_score + adj, 100);
  const amount = Number(base.claim?.claimed_amount);
  const limit = CONFIG.auto_approval_limit;
  const coverage = base.policy_rag?.coverage_status ?? 'UNKNOWN';
  const signs = base.warning_signs;
  const reused = signs.some(s => s.code === 'PHOTO_REUSED');

  // Investigation needs a reused photo or two independent rule-based signs,
  // so the LLM can never trigger an investigation on its own.
  let route;
  const route_reasons = [];
  if (reused) {
    route = 'fraud_investigation';
    route_reasons.push('Reused photo');
  } else if (risk >= CONFIG.investigate_at && signs.length >= CONFIG.min_signs_for_investigation) {
    route = 'fraud_investigation';
    route_reasons.push(`Risk score ${risk} with ${signs.length} warning signs`);
  } else {
    if (risk >= CONFIG.auto_approve_below) route_reasons.push(`Risk score ${risk} is ${CONFIG.auto_approve_below} or above`);
    if (!(amount <= limit)) route_reasons.push(Number.isFinite(amount) ? `Amount ${amount} is above the auto-approval limit ${limit}` : 'Amount unknown (invoice total not read)');
    if (coverage !== 'COVERED') route_reasons.push(`Coverage result is ${coverage}`);
    if (base.missing_inputs.length) route_reasons.push(`Missing agent results: ${base.missing_inputs.join(', ')}`);
    if (llm_error) route_reasons.push('LLM assessment failed');
    route = route_reasons.length ? 'human_review' : 'auto_approve';
    if (route === 'auto_approve') route_reasons.push(`Risk score ${risk} below ${CONFIG.auto_approve_below}, amount within limit, covered`);
  }

  return {
    json: {
      stage: 'decide',
      claim_id: base.claim?.claim_id,
      route,
      route_reasons,
      risk_score: risk,
      rule_score: base.rule_score,
      llm_adjustment: adj,
      warning_signs: signs,
      coverage: {
        status: coverage,
        cited_clauses: base.policy_rag?.cited_clauses ?? [],
        reasoning: base.policy_rag?.reasoning ?? '',
      },
      justification: llm.justification,
      additional_concerns: llm.additional_concerns ?? [],
      missing_inputs: base.missing_inputs,
      llm_error,
      llm_raw: llm_error ? llm_raw.slice(0, 3000) : undefined,
      decided_at: new Date().toISOString(),
    },
  };
});

// Reads every photo attached to the claim (binary images) and computes:
// - a fingerprint (SHA-256) to spot the same photo sent in another claim
// - the date the photo was taken, from its EXIF data (JPEG only)
// Claims sent without image files keep the photo fields they already have.

function sha256(bytes) {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const len = bytes.length;
  const total = Math.ceil((len + 9) / 64) * 64;
  const msg = new Uint8Array(total);
  msg.set(bytes);
  msg[len] = 0x80;
  const bits = len * 8;
  const view = new DataView(msg.buffer);
  view.setUint32(total - 8, Math.floor(bits / 0x100000000));
  view.setUint32(total - 4, bits >>> 0);
  const W = new Uint32Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < total; off += 64) {
    for (let t = 0; t < 16; t++) W[t] = view.getUint32(off + t * 4);
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      const s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const t1 = (h + S1 + ((e & f) ^ (~e & g)) + K[t] + W[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const t2 = (S0 + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0;
      d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  return H.map(x => x.toString(16).padStart(8, '0')).join('');
}

// Returns 'YYYY-MM-DD' from the JPEG's EXIF data, or null when there is none
// (screenshots and photos sent through WhatsApp usually have no EXIF).
function exifDate(bytes) {
  try {
    const v = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    if (v.getUint16(0) !== 0xffd8) return null;
    let off = 2;
    while (off + 4 <= bytes.length) {
      if (bytes[off] !== 0xff) return null;
      const marker = bytes[off + 1];
      if (marker === 0xda || marker === 0xd9) return null;
      const size = v.getUint16(off + 2);
      const isExif = marker === 0xe1 && String.fromCharCode(...bytes.slice(off + 4, off + 8)) === 'Exif';
      if (isExif) {
        const tiff = off + 10;
        const le = v.getUint16(tiff) === 0x4949;
        const u16 = p => v.getUint16(p, le);
        const u32 = p => v.getUint32(p, le);
        const readIfd = start => {
          const tags = {};
          const n = u16(start);
          for (let i = 0; i < n; i++) {
            const e = start + 2 + i * 12;
            tags[u16(e)] = { type: u16(e + 2), count: u32(e + 4), value: u32(e + 8), at: e + 8 };
          }
          return tags;
        };
        const text = t => {
          if (!t || t.type !== 2) return null;
          const p = t.count > 4 ? tiff + t.value : t.at;
          return String.fromCharCode(...bytes.slice(p, p + t.count)).replace(/\0.*$/, '');
        };
        const ifd0 = readIfd(tiff + u32(tiff + 4));
        const exif = ifd0[0x8769] ? readIfd(tiff + ifd0[0x8769].value) : {};
        const raw = text(exif[0x9003]) || text(exif[0x9004]) || text(ifd0[0x0132]);
        const m = /^(\d{4}):(\d{2}):(\d{2})/.exec(raw || '');
        return m ? `${m[1]}-${m[2]}-${m[3]}` : null;
      }
      off += 2 + size;
    }
  } catch (e) { /* unreadable EXIF counts as no date */ }
  return null;
}

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const claim = item.json.claim ?? item.json;
  const photo_info = [];

  for (const [key, file] of Object.entries(item.binary ?? {})) {
    if (!String(file.mimeType).startsWith('image/')) continue; // the invoice PDF is not a photo
    const bytes = new Uint8Array(await this.helpers.getBinaryDataBuffer(i, key));
    photo_info.push({ file: file.fileName || key, hash: sha256(bytes), taken_date: exifDate(bytes) });
  }

  const newClaim = photo_info.length
    ? {
        ...claim,
        photo_count: photo_info.length,
        photo_taken_dates: photo_info.map(p => p.taken_date).filter(Boolean),
        photo_hashes: photo_info.map(p => p.hash),
      }
    : { ...claim, photo_hashes: claim.photo_hashes ?? [] };

  const hashes = newClaim.photo_hashes;
  out.push({
    json: {
      ...item.json,
      claim: newClaim,
      photo_info,
          },
  });
}
return out;

// Compares this claim's photo fingerprints with the ones saved from earlier claims
// (n8n Data Table "photo hashes", shared with the Visual Inspection agent).
// A match from another claim means the photo was reused (+40 at the decide stage).
const result = $('Claim Checks').first().json;
const claim = $('Check Required Fields').first().json.claim;
const info = $('Read Photos').first().json.photo_info ?? [];
const hashes = claim.photo_hashes ?? [];
const mine = new Set(hashes);

const found = $('Find Photo Hashes').all().map(i => i.json).filter(r => r.hash && mine.has(r.hash));
const fromOtherClaims = found.filter(r => r.claim_id !== claim.claim_id);
const known = new Set(found.map(r => r.hash));

return [{
  json: {
    ...result,
    photo_checks: {
      photos_checked: hashes.length,
      photo_reused: fromOtherClaims.length > 0,
      reused_from_claims: [...new Set(fromOtherClaims.map(r => r.claim_id))],
      photo_taken_dates: claim.photo_taken_dates ?? [],
      photos_without_date: info.filter(p => !p.taken_date).map(p => p.file),
    },
    // Fingerprints seen for the first time, saved so later claims can be compared.
    _new_photo_rows: [...new Set(hashes)]
      .filter(h => !known.has(h))
      .map(h => ({ hash: h, claim_id: claim.claim_id, photo_key: (info.find(p => p.hash === h) || {}).file || '' })),
  },
}];

// Final answer of the validate stage, returned to the main workflow.
const { _new_photo_rows, ...result } = $('Photo Checks').first().json;
return [{ json: result }];

