// Step 1 of the scenario: turns the form answers into one claim and gives it an ID.
// Photos keep their binary keys (photos_0, photos_1...), the invoice PDF goes to "invoice".
// There is no amount field: the amount claimed is the invoice total, read later by the OCR agent.
const f = $input.first().json;
const bin = $input.first().binary ?? {};
const pad = n => String(n).padStart(2, '0');
const now = new Date();
const claim_id = `CLM-${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const clean = v => String(v ?? '').trim();

const photos = {};
let invoice = null;
for (const [key, file] of Object.entries(bin)) {
  if (key.startsWith('invoice')) invoice = file;
  else if (String(file.mimeType).startsWith('image/')) photos[`photos_${Object.keys(photos).length}`] = file;
}

const date = clean(f.incident_date).slice(0, 10);
const time = /^\d{1,2}:\d{2}$/.test(clean(f.incident_time)) ? clean(f.incident_time).padStart(5, '0') : '';
const location = { street: clean(f.street), city: clean(f.city), postal_code: clean(f.postal_code), country: clean(f.country) || 'Tunisia',
  // Map pin from the claim page (empty when the client used the form without the map).
  lat: Number.isFinite(parseFloat(f.incident_lat)) ? parseFloat(f.incident_lat) : null,
  lon: Number.isFinite(parseFloat(f.incident_lon)) ? parseFloat(f.incident_lon) : null };

const claim = {
  claim_id,
  client_name: clean(f.full_name),
  client_email: clean(f.client_email),
  client_phone: clean(f.phone),
  incident_date: date,
  incident_time: time,
  incident_datetime: `${date}T${time || '12:00'}:00`,
  location,
  // One line for the map lookup of the plausibility agent: "street, postal code city, country"
  incident_location: [location.street, [location.postal_code, location.city].filter(Boolean).join(' '), location.country].filter(Boolean).join(', '),
  description: clean(f.description),
  claim_type: 'not specified (see description)',
  photo_count: Object.keys(photos).length,
  has_invoice: invoice !== null,
  submitted_at: now.toISOString(),
};

return [{ json: { stage: 'validate', claim }, binary: { ...photos, ...(invoice ? { invoice } : {}) } }];

// Images -> Visual Inspection agent. It describes the accident seen on the photos.
const { claim } = $('Prepare Claim').first().json;
const { invoice, ...photos } = $('Prepare Claim').first().binary ?? {};
return [{
  json: {
    claim_id: claim.claim_id,
    description: claim.description,
    incident_date: claim.incident_date,
    photo_count: claim.photo_count,
    claim_type: claim.claim_type,
  },
  binary: photos,
}];

// Invoice -> OCR agent. The Invoice Parser reads a file path, so the uploaded PDF is first saved to
// /data/invoices/<claim_id>.pdf (the project's data folder, shared with n8n).
const { claim } = $('Prepare Claim').first().json;
const { invoice } = $('Prepare Claim').first().binary ?? {};
return [{ json: { file_path: `/data/invoices/${claim.claim_id}.pdf`, claim_id: claim.claim_id }, binary: { invoice } }];

// Description -> Policy RAG agent. It searches the policy for the clauses that fit this accident.
const { claim } = $('Prepare Claim').first().json;
return [{
  json: {
    claim: {
      claim_id: claim.claim_id,
      claim_type: claim.claim_type,
      incident_date: claim.incident_date,
      incident_time: claim.incident_time,
      description: claim.description,
    },
  },
}];

// Step 3 of the scenario: the four agents' answers come back to the validation agent.
// They are put in the format the fraud scoring reads. An agent that failed is passed as
// { error: true }, which sends the claim to a human (never auto-approved).
const failure = (r, name) => {
  if (r && !r.error) return null;
  const e = r?.error;
  const message = typeof e === 'string' ? e : e?.message || r?.error_message || r?.reason || `${name} returned nothing`;
  return { error: true, error_message: String(message).slice(0, 500) };
};
const first = name => { try { return $(name).first().json; } catch (e) { return null; } };

const validation = $('Validation Result').first().json;

// Visual Inspection: field names differ slightly from the scoring's.
const v = first('Visual Inspection Agent');
const visual = failure(v, 'Visual Inspection') || {
  ...v,
  damaged_parts: v.damaged_parts ?? v.damaged_items ?? [],
  photo_reused: v.duplicate_photo_detected === true,
  reused_from_claims: (v.duplicate_photos || []).map(d => d.previous_claim_id),
  same_vehicle_across_photos: v.same_asset_across_photos,
};

// Invoice OCR, with the part codes added by "Map Invoice Parts"
const inv = first('Map Invoice Parts');
const invoice = failure(inv, 'Invoice OCR') || inv;

const rag = first('Policy RAG Agent');
const policy_rag = failure(rag && rag.coverage_status ? rag : { error: rag?.error || 'no coverage_status in the answer' }, 'Policy RAG') || {
  coverage_status: rag.coverage_status, cited_clauses: rag.cited_clauses, reasoning: rag.reasoning, eval_score: rag.eval_score,
};

const pl = first('Incident Plausibility Agent');
const plausibility = failure(pl && pl.agent ? pl : { error: pl?.error || 'no result' }, 'Incident Plausibility') || pl;

// The amount claimed is the invoice total (the form has no amount field).
const total = Number(invoice.key_info?.total ?? invoice.invoice?.total);
const claim = { ...$('Check Required Fields').first().json.claim };
if (Number.isFinite(total) && total > 0) claim.claimed_amount = total;

return [{ json: { stage: 'decide', claim, validation, visual, invoice, policy_rag, plausibility } }];

// A claim that fails validation (missing information, no photo or invoice, a date in the future...)
// is rejected here, before any AI agent runs.
const v = $input.first().json;
const { claim } = $('Prepare Claim').first().json;
const reasons = v.error
  ? [`Validation could not run: ${v.error?.message || v.error}`]
  : (v.reasons?.length ? v.reasons : ['Claim is not valid']);
return [{
  json: {
    ...claim,
    claimed_amount: null,
    route: 'rejected',
    risk_score: null,
    warning_signs: [],
    route_reasons: reasons,
    justification: '',
    missing_inputs: [],
    agents: {},
  },
}];

// The decision record (design section 4.7): the route, the score and why, plus what each agent said.
const d = $input.first().json;
const input = $('Collect Agent Results').first().json;
const { claim, validation, visual, invoice, policy_rag, plausibility } = input;
const ok = d.route && !d.error;
const failed = r => !r || r.error;
const { photo_hashes, photo_taken_dates, ...claimInfo } = claim;

return [{
  json: {
    ...claimInfo,
    claimed_amount: claim.claimed_amount ?? null,
    route: ok ? d.route : 'human_review',
    risk_score: d.risk_score ?? null,
    rule_score: d.rule_score ?? null,
    llm_adjustment: d.llm_adjustment ?? null,
    warning_signs: d.warning_signs ?? [],
    route_reasons: ok ? d.route_reasons : [`Decision agent failed: ${d.error?.message || d.error || 'no result'}`],
    justification: d.justification ?? '',
    missing_inputs: d.missing_inputs ?? [],
    // What each agent produced (step 2 of the scenario)
    agents: {
      visual: failed(visual)
        ? { ok: false, error: visual?.error_message || 'no result' }
        : { ok: true, accident_description: visual.accident_description || visual.summary || '', severity: visual.damage_severity, damaged_parts: visual.damaged_parts || [] },
      invoice: failed(invoice)
        ? { ok: false, error: invoice?.error_message || 'no result' }
        : { ok: true, summary: invoice.summary || '', key_info: invoice.key_info || {}, status: invoice.status },
      policy_rag: failed(policy_rag)
        ? { ok: false, error: policy_rag?.error_message || 'no result' }
        : { ok: true, coverage_status: policy_rag.coverage_status, cited_clauses: policy_rag.cited_clauses || [], explanation: policy_rag.reasoning || '' },
      plausibility: failed(plausibility)
        ? { ok: false, error: plausibility?.error_message || 'no result' }
        : { ok: true, summary: plausibility.summary, score: plausibility.score, warning_signs: plausibility.warning_signs || [] },
      photo_checks: validation.photo_checks ?? null,
    },
  },
}];

// Step 4 of the scenario: one message for the client and one for the insurance team.
// The insurer always gets the full picture (score, warning signs, every agent's output).
// The client gets the decision and why, in plain words; when it is not a fraud case he also gets
// what his policy says about this accident (from the Policy RAG agent). The client is never told
// about a fraud suspicion (design section 4.8): a fraud case reads like a normal manual review to him.
const SETTINGS = {
  insurer_email: 'claims-team@example.com', // who receives the insurer message: change it to your address
  from_email: 'ClaimShield AI <claimshield@example.com>', // sender: use the address of your SMTP account
  company: 'ClaimShield Insurance',
};

const r = $input.first().json;
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const known = n => n !== null && n !== undefined && Number.isFinite(Number(n));
const money = n => (known(n) ? `${Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} TND` : 'unknown');
const when = `${r.incident_date}${r.incident_time ? ` at ${r.incident_time}` : ''}`;
const where = r.incident_location || '';
const loc = r.location || {};
const mapLink = loc.lat != null && loc.lon != null
  ? ` (<a href="https://www.openstreetmap.org/?mlat=${loc.lat}&mlon=${loc.lon}#map=18/${loc.lat}/${loc.lon}">pinned on the map</a>)` : '';
const a = r.agents || {};
const rag = a.policy_rag || {};
const firstName = String(r.client_name || '').split(' ')[0];

const ROUTES = {
  auto_approve: { label: 'Approved', color: '#0f7b4a', bg: '#e7f6ee', next: 'Approval email sent to the client. Create the payment request.' },
  human_review: { label: 'Human review', color: '#9a5b00', bg: '#fff4e0', next: 'An adjuster must review the claim and approve or reject it.' },
  fraud_investigation: { label: 'Fraud investigation', color: '#b42318', bg: '#fdecea', next: 'Open an investigation ticket. The client was NOT told about the suspicion.' },
  rejected: { label: 'Rejected', color: '#475467', bg: '#eef0f3', next: 'Nothing to do: the claim was rejected at validation, before any AI call.' },
};
const route = ROUTES[r.route] ? r.route : 'human_review';
const R = ROUTES[route];
const fraud = route === 'fraud_investigation';
// What the client sees: a fraud case shows as a review
const C = fraud ? ROUTES.human_review : R;

// ---------- shared email layout (inline styles: email clients ignore <style>) ----------
const FONT = "font-family:'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#1d2939;";
const h3 = t => `<h3 style="margin:22px 0 8px;font-size:15px;color:#101828">${t}</h3>`;
const p = t => `<p style="margin:0 0 10px;font-size:14px;line-height:1.6">${t}</p>`;
const ul = xs => `<ul style="margin:0 0 10px;padding-left:20px;font-size:14px;line-height:1.6">${xs.map(x => `<li>${x}</li>`).join('')}</ul>`;
const badge = (x, text) => `<span style="display:inline-block;background:${x.bg};color:${x.color};font-weight:600;font-size:13px;padding:4px 12px;border-radius:999px">${text || x.label}</span>`;
const layout = (title, body) => `<div style="${FONT}background:#f2f4f7;padding:24px 12px">
  <div style="max-width:640px;margin:0 auto;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #e4e7ec">
    <div style="background:#0b1f44;padding:18px 28px;color:#ffffff;font-size:16px;font-weight:600;letter-spacing:.3px">${esc(SETTINGS.company)}</div>
    <div style="padding:26px 28px">${title}${body}</div>
    <div style="padding:14px 28px;background:#f9fafb;color:#667085;font-size:12px">Claim reference ${esc(r.claim_id)} · processed by ClaimShield AI</div>
  </div></div>`;

// ---------- What the policy says about this case (from the RAG agent) ----------
const ragText = String(rag.explanation || '').replace(/^\s*(COVERED|EXCLUDED|REQUIRES_REVIEW|NOT COVERED)\b[\s:.,-]*/i, '').trim();
const COVERAGE = {
  COVERED: 'Your policy covers this damage.',
  EXCLUDED: 'Your policy does not seem to cover this damage.',
  REQUIRES_REVIEW: 'Whether your policy covers this damage will be confirmed by an adjuster.',
};
const policyBlock = rag.ok
  ? h3('What your policy says about your case')
    + `<div style="background:#f5f8ff;border-left:4px solid #3b5bdb;border-radius:8px;padding:12px 16px;margin-bottom:10px">`
    + p(`<b>${esc(COVERAGE[rag.coverage_status] || COVERAGE.REQUIRES_REVIEW)}</b>`)
    + (ragText ? p(esc(ragText)) : '')
    + (rag.cited_clauses?.length ? `<p style="margin:0;font-size:12px;color:#475467">Policy references: ${esc(rag.cited_clauses.join(', '))}</p>` : '')
    + `</div>`
  : '';

// ---------- Client reasons, in words that never mention fraud ----------
function clientReasons() {
  if (route === 'rejected') return r.route_reasons;
  if (route === 'auto_approve') {
    return ['We checked your photos, your invoice, the circumstances of the accident and your policy, and the claim can be approved automatically (amount within our automatic approval limit).'];
  }
  if (fraud) return ['Some details of your claim need to be checked by one of our adjusters.'];
  const out = [];
  for (const reason of r.route_reasons || []) {
    if (/auto-approval limit/.test(reason)) out.push(`The repair amount (${money(r.claimed_amount)}) is above what we can approve automatically.`);
    else if (/Amount unknown/.test(reason)) out.push('We could not read the total amount on your invoice.');
    else if (/Coverage result is (\w+)/.test(reason)) {
      const s = /Coverage result is (\w+)/.exec(reason)[1];
      out.push(s === 'EXCLUDED' ? 'Your policy may not cover this damage (see below).' : 'Whether your policy covers this case must be confirmed by an adjuster.');
    } else if (/Missing agent results: (.*)/.test(reason)) {
      const names = { visual: 'analyse your photos', invoice: 'read your invoice', policy_rag: 'check your policy', plausibility: 'check the circumstances of the accident' };
      for (const m of /Missing agent results: (.*)/.exec(reason)[1].split(', ')) out.push(`We could not ${names[m] || m} automatically.`);
    } else if (/Risk score/.test(reason) || /LLM/.test(reason)) out.push('Some details of your claim need to be checked by a person.');
  }
  const unique = [...new Set(out)];
  return unique.length ? unique : ['Your claim needs a manual check.'];
}

let clientSubject, clientIntro;
if (route === 'auto_approve') {
  clientSubject = `Your claim ${r.claim_id} is approved`;
  clientIntro = p(`Good news: your claim for the accident of ${esc(when)} is <b>approved</b>.`)
    + p(`Repair invoice: <b>${money(r.claimed_amount)}</b>. The deductible of your policy applies (see below); our payment team will confirm the amount paid.`);
} else if (route === 'rejected') {
  clientSubject = `Your claim ${r.claim_id} could not be accepted`;
  clientIntro = p(`We could not accept your claim for the accident of ${esc(when)}.`);
} else {
  clientSubject = `Your claim ${r.claim_id} is being reviewed`;
  clientIntro = p(`We have received your claim for the accident of ${esc(when)}. One of our adjusters is reviewing it and will contact you within 2 working days.`);
}
const clientHtml = layout(
  `<div style="margin-bottom:14px">${badge(C, route === 'auto_approve' ? 'Approved' : route === 'rejected' ? 'Not accepted' : 'Under review')}</div>`,
  p(`Hello${firstName ? ` ${esc(firstName)}` : ''},`) + clientIntro
  + h3('Why') + ul(clientReasons().map(esc))
  + (!fraud && route !== 'rejected' ? policyBlock : '')
  + p(`If you have any question, reply to this email and quote your claim reference <b>${esc(r.claim_id)}</b>.`)
  + p(`Kind regards,<br>${esc(SETTINGS.company)}`));

// ---------- Insurer message: everything ----------
const pc = a.photo_checks;
const row = (name, html) => `<tr><td style="padding:10px 12px;vertical-align:top;color:#475467;font-size:13px;white-space:nowrap;border-top:1px solid #eaecf0">${name}</td><td style="padding:10px 12px;font-size:13px;line-height:1.55;border-top:1px solid #eaecf0">${html}</td></tr>`;
const failedText = x => `<span style="color:#b42318">failed: ${esc(x?.error)}</span>`;
const pl = a.plausibility || {};
const insurerHtml = layout(
  `<div style="margin-bottom:14px">${badge(R)}${r.risk_score != null ? `<span style="margin-left:12px;font-size:14px">Risk score <b style="font-size:18px">${r.risk_score}</b>/100 <span style="color:#667085">(rules ${r.rule_score}/60 + AI ${r.llm_adjustment})</span></span>` : ''}</div>`,
  p(`<b>Next action:</b> ${esc(R.next)}`)
  + h3('Why') + ul((r.route_reasons || []).map(esc))
  + h3('Warning signs (design rules, section 4.6)')
  + ((r.warning_signs || []).length ? ul(r.warning_signs.map(s => `<b>${esc(s.code)}</b> (+${s.points}): ${esc(s.detail)}`)) : p('None'))
  + (r.justification ? p(`<b>AI risk assessment:</b> ${esc(r.justification)}`) : '')
  + (route === 'rejected' ? '' : h3('What each agent found') + `<table style="border-collapse:collapse;width:100%">
    ${row('Photos<br><small>Visual agent</small>', a.visual?.ok ? `${esc(a.visual.accident_description)}<br><span style="color:#667085">Severity ${esc(a.visual.severity)}/5 · damaged: ${esc((a.visual.damaged_parts || []).join(', '))}</span>` : failedText(a.visual))}
    ${row('Photo checks', pc ? `${pc.photos_checked} photo(s) · ${pc.photo_reused ? `<b style="color:#b42318">reused from ${esc(pc.reused_from_claims.join(', '))}</b>` : 'none reused'} · dates: ${esc(pc.photo_taken_dates.join(', ') || 'none in the files')}` : 'not checked')}
    ${row('Invoice<br><small>OCR agent</small>', a.invoice?.ok ? esc(a.invoice.summary) : failedText(a.invoice))}
    ${row('Circumstances<br><small>Plausibility agent</small>', pl.ok ? `${esc(pl.summary)}${(pl.warning_signs || []).length ? ul(pl.warning_signs.map(s => `${esc(s.code)} (+${s.points}, ${esc(s.confidence)}): ${esc(s.evidence)}`)) : ''}` : failedText(pl))}
    ${row('Policy<br><small>RAG agent</small>', rag.ok ? `<b>${esc(rag.coverage_status)}</b> ${esc((rag.cited_clauses || []).join(', '))}<br>${esc(ragText)}` : failedText(rag))}
  </table>`)
  + h3('Claim')
  + p(`${esc(r.client_name)} · ${esc(r.client_email)}${r.client_phone ? ` · ${esc(r.client_phone)}` : ''}<br>Accident on ${esc(when)}${where ? `, ${esc(where)}` : ''}${mapLink}<br>Amount: ${money(r.claimed_amount)}`)
  + p(`<i>"${esc(r.description)}"</i>`));

return [{
  json: {
    ...r,
    client: { to: r.client_email, subject: clientSubject, html: clientHtml },
    insurer: {
      to: SETTINGS.insurer_email,
      subject: `[ClaimShield] ${r.claim_id}: ${R.label}${r.risk_score != null ? `, risk ${r.risk_score}/100` : ''}`,
      html: insurerHtml,
    },
    from_email: SETTINGS.from_email,
  },
}];

// The page the client sees after submitting the form. For the demo it also shows the insurer message
// and whether each email went out.
const m = $('Write Messages').first().json;
// A sent email returns the mail server's answer (messageId, accepted). When sending fails (for example
// no SMTP credential yet) the node passes the message through instead, so the page says "not sent".
const sent = name => {
  const out = $(name).first().json;
  return out.messageId || out.accepted
    ? '<span class="pill ok">Email sent</span>'
    : '<span class="pill ko">Email not sent: add an SMTP credential to this Email node</span>';
};
const card = (title, to, subject, status, html) => `
  <section class="msg">
    <div class="meta"><span class="who">${title}</span><span class="to">to ${to || '?'}</span>${status}</div>
    <div class="subject">${subject}</div>
    <div class="body">${html}</div>
  </section>`;
const html = `<style>
  body{background:#eef1f6;margin:0}
  .cs{max-width:760px;margin:0 auto;padding:28px 16px 48px;font-family:'Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#1d2939;text-align:left}
  .cs .top{display:flex;align-items:center;gap:12px;margin-bottom:6px}
  .cs .logo{width:40px;height:40px;border-radius:10px;background:#0b1f44;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700}
  .cs h1{font-size:22px;margin:0}
  .cs .lead{color:#475467;font-size:14px;margin:4px 0 20px}
  .cs .msg{background:#fff;border:1px solid #e4e7ec;border-radius:14px;box-shadow:0 6px 24px rgba(16,24,40,.06);margin:18px 0;overflow:hidden}
  .cs .meta{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:14px 18px;border-bottom:1px solid #eaecf0;background:#f9fafb;font-size:13px}
  .cs .who{font-weight:600}
  .cs .to{color:#667085}
  .cs .pill{margin-left:auto;padding:3px 10px;border-radius:999px;font-size:12px;font-weight:600}
  .cs .pill.ok{background:#e7f6ee;color:#0f7b4a}
  .cs .pill.ko{background:#fdecea;color:#b42318}
  .cs .subject{padding:14px 18px 0;font-weight:600;font-size:15px}
  .cs .body > div{background:transparent !important;padding:12px 6px !important}
</style>
<div class="cs">
  <div class="top"><div class="logo">CS</div><h1>Claim ${m.claim_id} received</h1></div>
