parameters.jsCode:
// Gives every invoiced part its code from the shared parts vocabulary (front_bumper, taillight_left...),
// the same codes the Visual Inspection and Incident Plausibility agents use, so parts can be compared.
// Invoices are free text, often in French: "Pare-choc AR", "Phare avant gauche", "Rétroviseur D".
// A part whose side or position is not written stays without a code and is not compared.
const inv = $input.first().json;
if (inv.error) return [{ json: inv }];

const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const has = (t, re) => re.test(` ${t} `);
const LEFT = / (g|gauche|left|lh|gche) /, RIGHT = / (d|dr|droit|droite|right|rh|dte) /;
const FRONT = / (av|avant|front|fr|anterieur) /, REAR = / (ar|arr|arriere|rear|back|posterieur) /;
const side = t => (has(t, LEFT) ? 'left' : has(t, RIGHT) ? 'right' : null);

function code(text) {
  const t = norm(text);
  if (!t) return null;
  const s = side(t);
  if (has(t, / pare ?brise | windshield | windscreen /)) return 'windshield';
  if (has(t, / lunette | rear window /)) return 'rear_window';
  if (has(t, / (feu|feux|stop|catadioptre) (ar|arr|arriere) | taillight | tail light | rear light | feu arriere | feux arriere /)) return s && `taillight_${s}`;
  if (has(t, / phare | optique | projecteur | headlight | headlamp /)) return s && `headlight_${s}`;
  if (has(t, / pare ?chocs? | bumper | bouclier /)) return has(t, REAR) ? 'rear_bumper' : has(t, FRONT) ? 'front_bumper' : null;
  if (has(t, / capot | hood | bonnet /)) return 'hood';
  if (has(t, / coffre | hayon | trunk | tailgate | boot /)) return 'trunk_lid_tailgate';
  if (has(t, / calandre | grille /)) return 'front_grille';
  if (has(t, / radiateur | radiator /)) return 'radiator';
  if (has(t, / custode | quarter /) || (has(t, / aile | fender | wing /) && has(t, REAR))) return s && `quarter_panel_rear_${s}`;
  if (has(t, / aile | garde ?boue | fender | wing /)) return s && `fender_front_${s}`;
  if (has(t, / portes? | portiere | door /)) {
    const pos = has(t, REAR) ? 'rear' : has(t, FRONT) ? 'front' : null;
    return pos && s && `door_${pos}_${s}`;
  }
  if (has(t, / retro | retroviseur | mirror /)) return s && `mirror_${s}`;
  if (has(t, / vitre | glace | side window /)) return 'side_window';
  if (has(t, / pavillon | toit | roof /)) return 'roof';
  if (has(t, / jante | rim | enjoliveur /)) return 'wheel_rim';
  if (has(t, / pneu | tyre | tire /)) return 'tire';
  if (has(t, / amortisseur | suspension | triangle | rotule | shock absorber /)) return 'suspension';
  if (has(t, / airbag /)) return 'airbag';
  if (has(t, / moteur | engine | alternateur | courroie | carter /)) return 'engine_component';
  return null;
}

const line_items = (inv.line_items || []).map(li => ({ ...li, part_code: li.type === 'part' ? code(li.part) : null }));
return [{ json: { ...inv, line_items, part_codes: [...new Set(line_items.map(li => li.part_code).filter(Boolean))] } }];

// Input of the Incident Plausibility agent, taken from the claim form only: what happened,
// when, and where (the pin on the map, or else the street, city, postal code and country typed).
// The agent checks the story against the map and the weather at that place and time.
const { claim } = $('Prepare Claim').first().json;
return [{
  json: {
    claim: {
      claim_id: claim.claim_id,
      incident_datetime: claim.incident_datetime,
      incident_location: claim.incident_location,
      incident_address: claim.location,
      // The map pin, when the client placed one: the agent then uses it instead of the address.
      incident_lat: claim.location.lat,
      incident_lon: claim.location.lon,
      description: claim.description,
    },
  },
}];
